                    return obj[kx], obj[ky]
        return default

    def mv(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def dist(a, b):
        return abs(b[0] - a[0]) + abs(b[1] - a[1])

    def get_cells(obs, keys):
