    env = obs.get("environment_name", "") or obs.get("game_name", "") or ""
    sx, sy = pos(obs.get("self_position", obs.get("agent_position", (0, 0))), (0, 0))
    ox, oy = pos(obs.get("opponent_position", obs.get("enemy_position", (sx, sy))), (sx, sy))
    w = obs.get("grid_width", obs.get("width", 0)) if isinstance(obs, dict) else 0
    h = obs.get("grid_height", obs.get("height", 0)) if isinstance(obs, dict) else 0

    # Generic threat/goal lists
    resources = get_cells(obs, ("resources", "resource_positions", "targets", "food", "collectibles"))
    enemies = get_cells(obs, ("opponent_positions", "enemy_positions", "enemies", "opponents"))
    allies = get_cells(obs, ("allied_positions", "teammate_positions", "friends", "allies"))
    frontier = get_cells(obs, ("frontier_cells", "border_cells", "target_cells", "unclaimed_cells", "neutral_cells"))
    enemy_territory = get_cells(obs, ("opponent_territory", "enemy_territory", "enemy_cells"))

    # Pursuit/evasion: if role is pursuer, chase; if evader, move away from nearest threat or toward far corner.
    if env == "pursuit_evasion":
