            return mv((sx, sy), corner)

    # Resource collection: go to nearest resource, but if none, follow ally/opponent cues conservatively.
    if resources:
        best = min(resources, key=lambda c: dist((sx, sy), c))
        return mv((sx, sy), best)

    # If a teammate exists, avoid clumping too much by heading toward the nearest shared target-ish location.
    if allies:
        ax, ay = min((pos(a, (sx, sy)) for a in allies), key=lambda c: dist((sx, sy), c))
        if abs(ax - sx) + abs(ay - sy) > 1:
            return mv((sx, sy), (ax, ay))

    # Fallback: move away from opponent if close, else toward center if known, else stay.
